   and not exists(select 1 from pg_policy p where p.polrelid=c.oid)
   and (select count(*) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped)=jsonb_array_length(e->'columns')
   and not exists(select 1 from jsonb_array_elements(e->'columns') with ordinality expected(a,position)
    where not exists(select 1 from pg_attribute a where a.attrelid=c.oid and a.attnum=expected.position and not a.attisdropped
     and a.attname=expected.a->>'name' and format_type(a.atttypid,a.atttypmod)=expected.a->>'type'
     and a.attnotnull=(expected.a->>'notNull')::boolean and a.attidentity='' and a.attgenerated=''
     and a.atthasdef=((expected.a->'defaultSource')<>'null'::jsonb)))
 ) from finance27_relation
 union all select 'finance27_constraint_set',e->>'name',
  (select count(*) from pg_constraint c where c.conrelid=to_regclass(e->>'name') and c.contype<>'n') =
   jsonb_array_length(e->'constraints') +
   (select count(*) from finance27_constraint x where x.e->>'relation'=finance27_relation.e->>'name' and x.e->>'type'='t')
  and (select count(*) from pg_constraint c where c.conrelid=to_regclass(e->>'name') and c.contype='c')
   =(select count(*) from jsonb_array_elements(e->'constraints') k where k->>'kind'='check')
  and not exists(select 1 from pg_constraint c where c.conrelid=to_regclass(e->>'name') and c.contype<>'n'
   and (not c.convalidated or not c.conislocal))
  and not exists(select 1 from jsonb_array_elements(e->'constraints') k where k->>'kind'<>'check' and
   1<>(select count(*) from pg_constraint c where c.conrelid=to_regclass(e->>'name')
    and c.contype=(case k->>'kind' when 'primary_key' then 'p' when 'unique' then 'u' when 'foreign_key' then 'f' end)::"char"
    and c.condeferrable=(k->>'deferrable')::boolean and c.condeferred=(k->>'initiallyDeferred')::boolean
    and (k->'nameFromSource'='null'::jsonb or c.conname=k->>'nameFromSource')
    and (select array_agg(a.attname::text order by u.position) from unnest(c.conkey) with ordinality u(n,position) join pg_attribute a on a.attrelid=c.conrelid and a.attnum=u.n)
      =array(select jsonb_array_elements_text(k->'columns'))
    and (k->>'kind'<>'foreign_key' or c.confrelid=to_regclass(k->>'target') and c.confmatchtype='s'
     and c.confupdtype='a' and c.confdeltype=(case k->>'onDelete' when 'CASCADE' then 'c' else 'a' end)::"char"
     and (select array_agg(a.attname::text order by u.position) from unnest(c.confkey) with ordinality u(n,position) join pg_attribute a on a.attrelid=c.confrelid and a.attnum=u.n)
       =array(select jsonb_array_elements_text(k->'targetColumns')))))
  and not exists(select 1 from jsonb_array_elements(e->'constraints') k where k->>'kind'='check' and k->'nameFromSource'<>'null'::jsonb and
   not exists(select 1 from pg_constraint c where c.conrelid=to_regclass(e->>'name') and c.contype='c' and c.conname=k->>'nameFromSource'
    and c.convalidated and c.conislocal and not c.connoinherit))
 from finance27_relation
 union all select 'finance27_explicit_index',e->>'name',exists(
  select 1 from pg_index i join pg_class c on c.oid=i.indexrelid join pg_am am on am.oid=c.relam
  where i.indrelid=to_regclass(e->>'relation') and c.relname=e->>'name' and c.relnamespace='app_private'::regnamespace
   and pg_get_userbyid(c.relowner)='postgres' and am.amname='btree' and i.indisunique=(e->>'unique')::boolean
   and not i.indisprimary and not i.indisexclusion and not i.indnullsnotdistinct and i.indimmediate and i.indisvalid and i.indisready and i.indislive
   and i.indexprs is null and (i.indpred is not null)=((e->'predicateSource')<>'null'::jsonb)
   and i.indnkeyatts=jsonb_array_length(e->'keys') and i.indnatts=jsonb_array_length(e->'keys')+jsonb_array_length(e->'include')
   and (select array_agg(a.attname::text order by u.position) from unnest(i.indkey) with ordinality u(n,position) join pg_attribute a on a.attrelid=i.indrelid and a.attnum=u.n)
     =array(select jsonb_array_elements_text((e->'keys')||(e->'include')))
   and not exists(select 1 from unnest(i.indoption) options(value) where value<>0)
   and not exists(select 1 from unnest(i.indclass) o join pg_opclass pc on pc.oid=o where not pc.opcdefault or pc.opcmethod<>c.relam)
   and not exists(select 1 from unnest(i.indcollation) collations(value) where value<>0)
 ) from finance27_index
 union all select 'finance27_all_indexes',e->>'name',
  (select count(*) from pg_index i where i.indrelid=to_regclass(e->>'name'))=
   (select count(*) from jsonb_array_elements(e->'constraints') k where k->>'kind' in ('primary_key','unique'))+
   (select count(*) from finance27_index x where x.e->>'relation'=finance27_relation.e->>'name')
  and not exists(select 1 from pg_constraint k left join pg_index i on i.indexrelid=k.conindid
   join pg_class c on c.oid=k.conindid join pg_am a on a.oid=c.relam
   where k.conrelid=to_regclass(e->>'name') and k.contype in ('p','u')
    and (i.indexrelid is null or not i.indisunique or not i.indisvalid or not i.indisready or not i.indislive or not i.indimmediate or i.indnullsnotdistinct
     or i.indisprimary<>(k.contype='p') or i.indisexclusion or i.indexprs is not null or i.indpred is not null
     or array(select unnest(i.indkey))<>k.conkey or i.indnkeyatts<>cardinality(k.conkey) or i.indnatts<>cardinality(k.conkey) or a.amname<>'btree'))
 from finance27_relation
 union all select 'finance27_trigger',(e->>'relation')||'.'||(e->>'name'),exists(
  select 1 from pg_trigger t where t.tgrelid=to_regclass(e->>'relation') and t.tgname=e->>'name' and not t.tgisinternal
   and t.tgfoid=to_regprocedure(e->>'function') and t.tgtype=(e->>'tgtype')::smallint and t.tgenabled='O'
   and t.tgdeferrable=(e->>'deferrable')::boolean and t.tginitdeferred=(e->>'initiallyDeferred')::boolean
   and (t.tgconstraint<>0)=(e->>'constraint')::boolean and t.tgnargs=0 and t.tgargs=''::bytea and t.tgattr=''::int2vector and t.tgqual is null
   and t.tgoldtable is null and t.tgnewtable is null
 ) from finance27_trigger
 union all select 'finance27_trigger_set',e->>'name',
  (select count(*) from pg_trigger t where t.tgrelid=to_regclass(e->>'name') and not t.tgisinternal)=
   (select count(*) from finance27_trigger x where x.e->>'relation'=finance27_relation.e->>'name')
 from finance27_relation
 union all select 'finance27_legacy_projection_trigger',name,exists(
  select 1 from pg_trigger t where t.tgrelid=to_regclass(name) and t.tgname='finance_project' and not t.tgisinternal
   and t.tgfoid=to_regprocedure('app_private.finance_project()') and t.tgtype=23 and t.tgenabled='O'
   and not t.tgdeferrable and not t.tginitdeferred and t.tgconstraint=0 and t.tgnargs=0 and t.tgargs=''::bytea and t.tgattr=''::int2vector and t.tgqual is null)
 from (values('public.fin_accounts'),('public.fin_transactions')) legacy(name)
 union all select 'finance27_constraint_definition',(e->>'relation')||'.'||(e->>'name'),exists(
  select 1 from pg_constraint c where c.conrelid=to_regclass(e->>'relation') and c.conname=e->>'name'
   and c.contype=(e->>'type')::"char" and c.conislocal=(e->>'local')::boolean
   and c.convalidated=(e->>'validated')::boolean and c.connoinherit=(e->>'noInherit')::boolean
   and c.coninhcount=(e->>'inheritanceCount')::integer and c.conparentid=0
   and c.condeferrable=(e->>'deferrable')::boolean and c.condeferred=(e->>'initiallyDeferred')::boolean
   and pg_get_constraintdef(c.oid,false)=e->>'definition'
   and pg_get_expr(c.conbin,c.conrelid,false) is not distinct from e->>'expression'
 ) from finance27_constraint
 union all select 'finance27_constraint_trigger_link','app_private.finance_series_permits.finance_series_permit_zero',exists(
  select 1 from pg_constraint c join pg_trigger t on t.tgconstraint=c.oid
  where c.conrelid=to_regclass('app_private.finance_series_permits') and c.conname='finance_series_permit_zero' and c.contype='t'
   and c.condeferrable and c.condeferred and c.convalidated and c.conislocal and c.connoinherit and c.coninhcount=0 and c.conparentid=0
   and t.tgrelid=c.conrelid and t.tgname=c.conname and not t.tgisinternal
   and t.tgfoid=to_regprocedure('app_private.fsv2_permit_zero()') and t.tgtype=21 and t.tgenabled='O'
   and t.tgdeferrable and t.tginitdeferred and t.tgnargs=0 and t.tgargs=''::bytea and t.tgattr=''::int2vector
   and t.tgqual is null and t.tgoldtable is null and t.tgnewtable is null
   and 1=(select count(*) from pg_trigger linked where linked.tgconstraint=c.oid)
 )
 union all select 'finance27_column_default',(e->>'relation')||'.'||(e->>'column'),exists(
  select 1 from pg_attribute a join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
  where a.attrelid=to_regclass(e->>'relation') and a.attname=e->>'column' and a.attnum>0 and not a.attisdropped
   and pg_get_expr(d.adbin,d.adrelid,false)=e->>'expression'
 ) from finance27_column_default
 union all select 'finance27_function_default',e->>'signature',exists(
  select 1 from pg_proc p where p.oid=to_regprocedure(e->>'signature')
   and p.pronargdefaults=(e->>'count')::integer
   and p.proargnames=array(select jsonb_array_elements_text(e->'arguments'))
   and pg_get_expr(p.proargdefaults,0,false)=e->>'expression'
 ) from finance27_function_default
 union all select 'finance27_domain_events_predicate','public.domain_events.domain_events_entity_type_check',exists(
  select 1 from pg_constraint c cross join finance27_data d
  where c.conrelid=to_regclass('public.domain_events') and c.conname='domain_events_entity_type_check' and c.contype='c'
   and c.convalidated and c.conislocal and not c.connoinherit and c.coninhcount=0 and c.conparentid=0
   and not c.condeferrable and not c.condeferred
   and pg_get_constraintdef(c.oid,false)=d.data->'eventPredicate'->>'definition'
   and pg_get_expr(c.conbin,c.conrelid,false)=d.data->'eventPredicate'->>'expression'
 )
 union all select 'finance27_index_predicate','app_private.finance_goals_owner_image',exists(
  select 1 from pg_index i cross join finance27_data d
  where i.indexrelid=to_regclass('app_private.finance_goals_owner_image')
   and i.indrelid=to_regclass('app_private.finance_goals')
   and pg_get_indexdef(i.indexrelid)=d.data->'indexPredicate'->>'definition'
   and pg_get_expr(i.indpred,i.indrelid,false)=d.data->'indexPredicate'->>'expression'
 )
 union all select 'finance27_supported_engine','server_version_major',
  current_setting('server_version_num')::integer/10000 in (17,18)
)
select jsonb_build_object('version',1,'ok',bool_and(ok is true),'checks',count(*) filter(where not (check_name='default_acl_closed' and ok is true and object_name in(select object_name from redundant_owner_default_acl))),'deviations',coalesce(jsonb_agg(jsonb_build_object('check',check_name,'object',object_name) order by check_name,object_name) filter(where ok is distinct from true),'[]'::jsonb)) from checks;
rollback;
